public class TestParse {
    private static boolean tryParseInt(String text, int[] result) {
        try {
            int val = Integer.parseInt(text);
            if (Integer.toString(val).equals(text.replace("-", ""))) {
                result[0] = val;
                return true;
            }
            return false;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    private static boolean tryParseLong(String text, long[] result) {
        try {
            long val = Long.parseLong(text);
            if (Long.toString(val).equals(text.replace("-", ""))) {
                result[0] = val;
                return true;
            }
            return false;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    public static void main(String[] args) {
        int[] intResult = new int[1];
        long[] longResult = new long[1];

        // TOTP Period/Digits test cases
        System.out.println("3000000000 (overflow int): " + tryParseInt("3000000000", intResult));
        System.out.println("30 (valid int): " + tryParseInt("30", intResult) + " => " + intResult[0]);
        System.out.println("2147483647 (Integer.MAX_VALUE): " + tryParseInt("2147483647", intResult) + " => " + intResult[0]);
        System.out.println("2147483648 (MAX+1): " + tryParseInt("2147483648", intResult));

        // HOTP Counter test cases
        String maxLong = "9223372036854775807";
        String overLong = "1000000000000000000000";
        System.out.println(maxLong + " (Long.MAX_VALUE): " + tryParseLong(maxLong, longResult) + " => " + longResult[0]);
        System.out.println(overLong + " (overflow long): " + tryParseLong(overLong, longResult));
        System.out.println("1 (valid long): " + tryParseLong("1", longResult) + " => " + longResult[0]);
    }
}
